(10, '鞋类', 103, 20, 1),
(11, '背包与箱包', 103, 30, 1),
(6, '家用电器', 104, 10, 1),
(7, '生活用品', 104, 20, 1),
(12, '家居', 104, 30, 1),
(13, '运动用品', 105, 10, 1),
(8, '办公用品', 106, 10, 1)
ON DUPLICATE KEY UPDATE
    `name` = VALUES(`name`),
    `parent_id` = VALUES(`parent_id`),
    `sort_order` = VALUES(`sort_order`),
    `status` = VALUES(`status`);

