-- Verification queries
SELECT COUNT(*) AS seeded_product_count
FROM `product`
WHERE `id` BETWEEN 100001 AND 100100
  AND `cover_url` LIKE '%seed=ec01%';

SELECT COUNT(*) AS seeded_sku_count
FROM `sku`
WHERE `sku_code` LIKE 'EC01-DEV-%';

SELECT
    SUM(`stock` BETWEEN 10 AND 200) AS normal_stock_skus,
    SUM(`stock` BETWEEN 1 AND 5) AS low_stock_skus,
    SUM(`stock` = 0) AS sold_out_skus,
    SUM(`status` = 0) AS disabled_skus
FROM `sku`
WHERE `sku_code` LIKE 'EC01-DEV-%';
